mapper.sql:
select em.evaluation_material_id as "evaluationMaterialId", em.evaluation_year as "evaluationYear", em.area_code as "areaCode", em.target_user_id as "targetUserId", em.source_achievement_id as "sourceAchievementId", em.generation_batch_id as "generationBatchId", cfv.formula_version_id as "formulaVersionId", cfv.rule_version_id as "ruleVersionId", cfv.formula_code as "formulaCode", em.calculated_score as "beforeScore", greatest( coalesce(cfv.lower_bound_score, -999999), least( coalesce(cfv.upper_bound_score, 999999), coalesce(score_source.base_score, em.calculated_score) ) )::numeric(10,2) as "afterScore", coalesce(( select max(scg.generation_no) + 1 from score_calculation_generations scg where scg.evaluation_material_id = em.evaluation_material_id ), 1) as "nextGenerationNo", em.material_status as "materialStatus", coalesce(em.material_snapshot_json ->> 'achievementTitle', concat('평가자료 ', em.evaluation_material_id)) as "achievementTitle" from evaluation_materials em join calculation_formula_versions cfv on cfv.active_yn = 'Y' left join lateral ( select esr.base_score from evaluation_score_rules esr join evaluation_management_items emi on emi.management_item_id = esr.management_item_id join evaluation_elements ee on ee.element_id = emi.element_id join evaluation_items ei on ei.item_id = ee.item_id join evaluation_areas ea on ea.area_id = ei.area_id where esr.rule_version_id = cfv.rule_version_id and esr.evaluation_year = em.evaluation_year and ea.area_code = em.area_code and esr.active_yn = 'Y' order by esr.score_rule_id limit 1 ) score_source on true where em.deleted_yn = 'N' and em.material_status = '인증'
and em.evaluation_year = #{criteria.normalizedEvaluationYear}
and em.area_code = #{criteria.normalizedAreaCode}
and em.target_user_id = #{criteria.normalizedTargetUserId}
and cfv.formula_version_id = #{criteria.normalizedFormulaVersionId}
